import{renderDiagram,renderCustomModel}from './visual.js?v=20261023-physicscomplete01';
import{organisationLevels,levelNames,organComplete,digestiveStops,digestiveIndex,absorptionSupported,enzymeState}from './organisation-models.js?v=20261023-physicscomplete01';
import{organisationFigure,digestiveFigure,enzymeFigure}from './organisation-figures.js?v=20261023-physicscomplete01';
const opts=(items,v)=>'<option value="">Choose…</option>'+items.map(([k,t])=>`<option value="${k}"${v===k?' selected':''}>${t}</option>`).join('');
export function showOrganisation(level='cell',w={}){if(!organisationLevels.includes(level))level='cell';const caption='<p class="diagram-caption">A functional hierarchy, not a calibrated magnification series. Counts, colours and layer shapes are symbolic. A stomach contains multiple tissues; the drawing is not a histological section.</p>';if(['system','organism'].includes(level)){renderDiagram(levelNames[level],'Cells → tissues → organs → systems → organism',organisationFigure(level,w)+caption,'BUILD LEVELS OF ORGANISATION');return;}renderCustomModel({name:levelNames[level],formula:level==='organ'?(w.layers||[]).length+' tissue types assembled':level==='tissue'?(w.count||1)+' similar muscle cell'+((w.count||1)===1?'':'s'):'One specialised muscle cell',kicker:'SCHEMATIC ORGANISATION MODEL',atoms:[],bonds:[],radius:3,viewKey:'organisation:'+level,startPaused:true,note:'Symbolic cells and tissues · scales differ',aria:levelNames[level]+'. '+(level==='organ'?'Selected tissue types: '+(w.layers||[]).join(', '):'Similar muscle cell group')+'. Use labelled controls to build and inspect the hierarchy.',diagram:organisationFigure(level,w)+caption,build:(g,T)=>{if(level==='organ'){for(const[key,i]of(w.layers||[]).map((k,i)=>[k,i])){const n={muscle:0,lining:1,gland:2}[key],ring=new T.Mesh(new T.TorusGeometry(.85+n*.22,.16,20,70,Math.PI*1.7),new T.MeshStandardMaterial({color:[0xed8b78,0xd4dfe7,0x91a5b3][n],roughness:.35}));ring.scale.set(.85,1.15,.65);ring.rotation.z=.35;ring.position.z=n*.08;g.add(ring);}const neck=new T.Mesh(new T.CylinderGeometry(.18,.18,1.1,28),new T.MeshStandardMaterial({color:0xb7c8d6,roughness:.35}));neck.position.set(-.25,1.5,0);g.add(neck);}else{const count=level==='cell'?1:Math.max(1,Math.min(6,Number(w.count)||1));for(let i=0;i<count;i++){const mesh=new T.Mesh(new T.SphereGeometry(1,32,20),new T.MeshStandardMaterial({color:0xed8b78,roughness:.3}));mesh.scale.set(.9,.22,.28);mesh.position.set(count===1?0:(i%2-.5)*2,-(Math.floor(i/2)-(Math.ceil(count/2)-1)/2)*.7,0);g.add(mesh);const nucleus=new T.Mesh(new T.SphereGeometry(.1,20,16),new T.MeshStandardMaterial({color:0x182e44}));nucleus.position.copy(mesh.position);nucleus.position.z=.28;g.add(nucleus);}}}});}
export function showDigestion(kind='mouth',w={}){const requested={mouth:0,stomach:2,intestine:3}[kind]??0,step=w.step??requested;renderDiagram(w.phase==='absorb'?'Across the intestinal lining':'Follow the digestive route',w.phase==='absorb'?'Digestion and absorption are different':'Several organs cooperate',digestiveFigure(step,w)+'<p class="diagram-caption">Schematic route and particles, not accurate organ shapes, sizes, digestion times or a membrane mechanism. Particle pieces represent molecular size qualitatively, not chemical stoichiometry.</p>','DIGEST · ABSORB · EGEST');}
export function showEnzyme(kind='fit',w={}){const step=w.step??(kind==='reaction'?2:kind==='unchanged'?3:0),f=enzymeState(w.substrate||'fit',step);renderCustomModel({name:'Enzyme and substrate',formula:f.products?'Products released · enzyme unchanged':f.bound?'Substrate fits the active site':f.fit?'Matching shape':'Different shape cannot bind',kicker:'SCHEMATIC LOCK-AND-KEY MODEL',atoms:[],bonds:[],radius:3,viewKey:'enzyme-fit',startPaused:true,note:'Shape analogy · no molecular detail or reaction rate',aria:'Simplified enzyme with an active-site notch. '+(f.products?'Products released; enzyme shape unchanged.':f.fit?'Matching substrate.':'Different substrate shape.')+' Use the controls to compare and step the reaction.',diagram:enzymeFigure(w.substrate||'fit',step)+'<p class="diagram-caption">The lock-and-key analogy explains specificity. Proteins are not rigid machined locks. Shapes, numbers and steps are symbolic; activation-energy, temperature and pH effects are developed in later lessons.</p>',build:(g,T)=>{const shape=new T.Shape();shape.moveTo(-1.5,-1);shape.bezierCurveTo(-2.2,-.5,-2.2,.5,-1.5,1);shape.lineTo(.35,1);shape.lineTo(.6,.55);shape.lineTo(.05,0);shape.lineTo(.6,-.55);shape.lineTo(.35,-1);shape.closePath();const body=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:.5,bevelEnabled:true,bevelSize:.07,bevelThickness:.07,bevelSegments:3,steps:1}),new T.MeshStandardMaterial({color:0x91a5b3,roughness:.28,metalness:.08}));body.position.z=-.25;g.add(body);const material=new T.MeshStandardMaterial({color:0xed8b78,roughness:.28});if(f.products){for(const [x,y,rot]of[[1.2,.45,.2],[1.9,-.35,-.3]]){const part=new T.Mesh(new T.ConeGeometry(.25,.45,3),material);part.position.set(x,y,.1);part.rotation.z=rot;g.add(part);}}else if(f.fit){const tri=new T.Shape();tri.moveTo(.6,-.55);tri.lineTo(.05,0);tri.lineTo(.6,.55);tri.closePath();const molecule=new T.Mesh(new T.ExtrudeGeometry(tri,{depth:.4,bevelEnabled:true,bevelSize:.03,bevelThickness:.03,bevelSegments:2}),material);molecule.position.set([1.5,.8,0][f.step]??0,0,-.2);g.add(molecule);}else{const molecule=new T.Mesh(new T.SphereGeometry(.45,32,20),material);molecule.position.set(f.step?1.3:2,0,0);g.add(molecule);}}});}
export function mountOrganisation(l,p,root,{save,done,feedback}){const w=p.widget,$=s=>root.querySelector(s),mode=l.widget,total=mode==='digestion-route'?4:3;w.task??=0;w.passed??=[];const task=w.task%total,tail='<button class="secondary" id="checkOrganisation">Check reasoning</button><button class="secondary" id="nextOrganisation">Next challenge →</button><p id="organisationProgress">'+w.passed.length+' / '+total+' complete</p>';const finish=()=>{if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;save();done();}save();$('#organisationProgress').textContent=w.passed.length+' / '+total+' complete';};
if(mode==='organisation-levels'){
if(task===0){w.count??=1;root.innerHTML='<p><b>1 / 3 · Build a tissue</b></p><p>Group similar specialised muscle cells. Predict what makes the group a tissue, then change its size.</p><label class="field-label" for="tissuePrediction">A tissue is…</label><select id="tissuePrediction" class="lab-select">'+opts([['similar','Similar cells sharing a function'],['any','Any nearby unrelated objects'],['organ','A whole organ system']],w.tissuePrediction)+'</select><label class="field-label" for="tissueCount">Cells in the teaching sample</label><input id="tissueCount" type="range" min="1" max="6" value="'+w.count+'"><p id="tissueReadout" aria-live="polite"></p>'+tail;const draw=()=>{showOrganisation(w.count===1?'cell':'tissue',w);$('#tissueReadout').textContent=w.count+' muscle cells represented. A group of4 here is only a small sample, not a real tissue cell count.';};$('#tissuePrediction').onchange=e=>{w.tissuePrediction=e.target.value;save();};$('#tissueCount').oninput=e=>{if(!w.tissuePrediction){e.target.value=w.count;feedback('Predict first, then build the tissue sample.',true);return;}w.count=Number(e.target.value);save();draw();};$('#checkOrganisation').onclick=()=>{if(w.count<4||w.tissuePrediction!=='similar'){feedback('Build a sample of at least4 muscle cells and explain the similar structure/function. A tissue is not just a large single cell.',true);return;}finish();feedback('Similar cells with a common function form a tissue. Real tissues contain many more cells.');};draw();
}else if(task===1){w.layers??=[];root.innerHTML='<p><b>2 / 3 · Assemble an organ</b></p><p>Add different tissue types to the stomach model. The rings symbolise contributions, not actual wall anatomy.</p><div class="model-actions">'+[['muscle','Muscle: movement'],['lining','Lining: surface'],['gland','Glandular: secretions']].map(([key,label])=>'<button class="secondary" data-tissue="'+key+'" aria-pressed="'+w.layers.includes(key)+'">'+label+'</button>').join('')+'</div><label class="field-label" for="organPrediction">The stomach is an organ because…</label><select id="organPrediction" class="lab-select">'+opts([['different','Different tissues work together'],['one','It is only one enlarged cell'],['system','Every organ is a whole organism']],w.organPrediction)+'</select><p id="organReadout" aria-live="polite"></p>'+tail;const draw=()=>{showOrganisation('organ',w);$('#organReadout').textContent='Tissue contributions: '+(w.layers.join(', ')||'none');for(const b of root.querySelectorAll('[data-tissue]'))b.setAttribute('aria-pressed',String(w.layers.includes(b.dataset.tissue)));};for(const b of root.querySelectorAll('[data-tissue]'))b.onclick=()=>{const key=b.dataset.tissue;w.layers=w.layers.includes(key)?w.layers.filter(x=>x!==key):[...w.layers,key];save();draw();};$('#organPrediction').onchange=e=>{w.organPrediction=e.target.value;save();};$('#checkOrganisation').onclick=()=>{if(!organComplete(w.layers)||w.organPrediction!=='different'){feedback('Assemble all three contributions. Different tissues cooperate in an organ; similar cells form a tissue.',true);return;}finish();feedback('The stomach is an organ containing several tissues with different functions.');};draw();
}else{w.levelViews??=[];root.innerHTML='<p><b>3 / 3 · Connect organs and systems</b></p><p>Inspect the system and organism levels. The diagram is a hierarchy, not a shared-size comparison.</p><div class="model-actions"><button class="secondary" data-level="system">Digestive system</button><button class="secondary" data-level="organism">Whole organism</button></div><label class="field-label" for="systemPrediction">A digestive system needs…</label><select id="systemPrediction" class="lab-select">'+opts([['organs','Several cooperating organs'],['cell','Only one cell'],['unrelated','Unrelated tissues with no shared role']],w.systemPrediction)+'</select><label class="field-label" for="organismPrediction">An organism contains…</label><select id="organismPrediction" class="lab-select">'+opts([['systems','Organ systems working together'],['stomach','Only its stomach'],['same','Only one kind of tissue']],w.organismPrediction)+'</select>'+tail;for(const b of root.querySelectorAll('[data-level]'))b.onclick=()=>{w.level=b.dataset.level;if(!w.levelViews.includes(w.level))w.levelViews.push(w.level);save();showOrganisation(w.level,w);};for(const key of['systemPrediction','organismPrediction'])$('#'+key).onchange=e=>{w[key]=e.target.value;save();};$('#checkOrganisation').onclick=()=>{if(!['system','organism'].every(v=>w.levelViews.includes(v))||w.systemPrediction!=='organs'||w.organismPrediction!=='systems'){feedback('Inspect both levels and connect cells→tissues→organs→systems→organism. The level changes function and scale, not simply the label.',true);return;}finish();feedback('Organs cooperate within systems; systems cooperate in an organism.');};showOrganisation(w.level||'system',w);}
}else if(mode==='digestion-route'){
if(task===0){w.routeStep??=0;root.innerHTML='<p><b>1 / 4 · Trace the food route</b></p><label class="field-label" for="routePrediction">Which route does food follow?</label><select id="routePrediction" class="lab-select">'+opts([['tract','Mouth → stomach → intestines'],['liver','Mouth → liver → kidneys'],['blood','Mouth → blood directly']],w.routePrediction)+'</select><button class="secondary" id="stepDigestiveRoute">Next organ →</button><p id="digestiveReadout" aria-live="polite"></p>'+tail;const draw=()=>{showDigestion('mouth',{step:w.routeStep});const s=digestiveStops[w.routeStep];$('#digestiveReadout').textContent=s.name+': '+s.role;};$('#routePrediction').onchange=e=>{w.routePrediction=e.target.value;save();};$('#stepDigestiveRoute').onclick=()=>{if(!w.routePrediction){feedback('Predict the route before tracing it.',true);return;}w.routeStep=Math.min(5,w.routeStep+1);save();draw();};$('#checkOrganisation').onclick=()=>{if(w.routeStep!==5||w.routePrediction!=='tract'){feedback('Trace through oesophagus, stomach and both intestines to the exit. Food does not pass through the liver or kidney on this route.',true);return;}finish();feedback('Several organs cooperate in digestion, absorption and removal of undigested material.');};draw();
}else if(task===1){w.breakStates??=[];root.innerHTML='<p><b>2 / 4 · Compare physical and chemical change</b></p><p>Chewing reduces food-piece size. Chemical digestion breaks large insoluble molecules into small soluble products.</p><label class="field-label" for="breakMode">Change to test</label><select id="breakMode" class="lab-select">'+opts([['physical','Break food into smaller pieces'],['chemical','Digest the large molecules']],w.breakMode)+'</select><button class="secondary" id="testBreakdown">Test the change</button><p id="breakReadout" aria-live="polite"></p><label class="field-label" for="breakReason">Small soluble products need…</label><select id="breakReason" class="lab-select">'+opts([['chemical','Chemical digestion of molecules'],['pieces','Chewing alone in every case'],['nothing','No molecular change']],w.breakReason)+'</select>'+tail;$('#breakMode').onchange=e=>{w.breakMode=e.target.value;save();};$('#testBreakdown').onclick=()=>{if(!w.breakMode){feedback('Choose a change to compare.',true);return;}if(!w.breakStates.includes(w.breakMode))w.breakStates.push(w.breakMode);save();const small=w.breakMode==='chemical';showDigestion('intestine',{phase:'absorb',small,cross:0});$('#breakReadout').textContent=small?'Small soluble products are now represented.':'Smaller food chunks can still contain large insoluble molecules.';};$('#breakReason').onchange=e=>{w.breakReason=e.target.value;save();};$('#checkOrganisation').onclick=()=>{if(!['physical','chemical'].every(v=>w.breakStates.includes(v))||w.breakReason!=='chemical'){feedback('Compare both changes. Molecular digestion, not merely making food chunks smaller, provides small soluble products.',true);return;}finish();feedback('Digestion changes large insoluble molecules into small soluble products. Absorption follows across a surface.');};showDigestion('intestine',{phase:'absorb',small:w.breakMode==='chemical'});
}else if(task===2){w.absorbSize??='large';w.absorbStep??=0;w.absorbSeen??=[];root.innerHTML='<p><b>3 / 4 · Cross the intestinal lining</b></p><label class="field-label" for="absorbSize">Molecule size</label><select id="absorbSize" class="lab-select">'+opts([['large','Large insoluble molecule'],['small','Small soluble product']],w.absorbSize)+'</select><button class="secondary" id="stepAbsorption">Step absorption test →</button><p id="absorbReadout" aria-live="polite"></p><label class="field-label" for="absorbReason">Absorption means…</label><select id="absorbReason" class="lab-select">'+opts([['blood','Products enter the bloodstream'],['break','Molecules are broken down'],['waste','All food is egested']],w.absorbReason)+'</select>'+tail;const draw=()=>{showDigestion('intestine',{phase:'absorb',small:w.absorbSize==='small',cross:w.absorbStep});$('#absorbReadout').textContent=absorptionSupported(w.absorbSize)&&w.absorbStep===3?'Small soluble product reaches blood.':w.absorbSize==='large'?'Large intact molecules are not absorbed in this model.':'Small product moving towards blood.';};$('#absorbSize').onchange=e=>{w.absorbSize=e.target.value;w.absorbStep=0;save();draw();};$('#stepAbsorption').onclick=()=>{w.absorbStep=Math.min(3,w.absorbStep+1);if(w.absorbStep===3&&!w.absorbSeen.includes(w.absorbSize))w.absorbSeen.push(w.absorbSize);save();draw();};$('#absorbReason').onchange=e=>{w.absorbReason=e.target.value;save();};$('#checkOrganisation').onclick=()=>{if(!['large','small'].every(v=>w.absorbSeen.includes(v))||w.absorbReason!=='blood'){feedback('Compare the large and small molecules through all3 steps. Absorption is movement into blood, distinct from digestion.',true);return;}finish();feedback('The small intestine provides an effective absorption surface for small soluble digestion products.');};draw();
}else{root.innerHTML='<p><b>4 / 4 · Follow what remains</b></p><label class="field-label" for="remainingWater">In the large intestine…</label><select id="remainingWater" class="lab-select">'+opts([['absorbed','Water is absorbed'],['all','All water is made from food'],['kidney','Food travels into the kidneys']],w.remainingWater)+'</select><label class="field-label" for="remainingFood">Undigested material…</label><select id="remainingFood" class="lab-select">'+opts([['egested','Leaves via rectum and anus'],['blood','All enters blood unchanged'],['lungs','Leaves via the lungs']],w.remainingFood)+'</select>'+tail;for(const key of['remainingWater','remainingFood'])$('#'+key).onchange=e=>{w[key]=e.target.value;save();};$('#checkOrganisation').onclick=()=>{if(w.remainingWater!=='absorbed'||w.remainingFood!=='egested'){feedback('Water is absorbed from the remaining contents. Undigested material passes towards the rectum and is egested through the anus.',true);return;}finish();feedback('Absorbed products and remaining undigested material take different routes.');};showDigestion('intestine',{step:5});}
}else{w.substrate??='fit';w.enzymeStep??=0;w.fitSeen??=[];w.enzymeCycles??=0;root.innerHTML='<p><b>'+(task+1)+' / 3 · '+['Test substrate specificity','Follow substrate and products','Reuse the enzyme'][task]+'</b></p><label class="field-label" for="enzymeSubstrate">Substrate shape</label><select id="enzymeSubstrate" class="lab-select">'+opts([['fit','Matching substrate'],['wrong','Different shape']],w.substrate)+'</select><button class="secondary" id="stepEnzyme">Step reaction model →</button><button class="secondary" id="reuseEnzyme">Release products; reuse enzyme</button><p id="enzymeReadout" aria-live="polite"></p><label class="field-label" for="enzymeReason">'+['Why does only one substrate fit?','What changes during this reaction?','Why can the enzyme act again?'][task]+'</label><select id="enzymeReason" class="lab-select">'+opts(task===0?[['shape','Complementary active-site shape'],['colour','Only its colour matters'],['cell','Every enzyme is a whole cell']]:task===1?[['products','Substrate becomes products'],['enzyme','Enzyme is consumed as food'],['nothing','Nothing changes']]:[['same','Enzyme remains unchanged'],['used','Enzyme is used up each time'],['living','Enzyme is a living cell']],w['enzymeReason'+task])+'</select>'+tail;
const draw=()=>{const f=enzymeState(w.substrate,w.enzymeStep);showEnzyme('fit',{substrate:w.substrate,step:w.enzymeStep});$('#enzymeReadout').textContent=(!f.fit?'Different shape: no fit at the active site.':f.products?'Products released; enzyme shape unchanged.':f.bound?'Substrate bound at the active site.':'Substrate approaching.')+' Completed cycles: '+w.enzymeCycles;};$('#enzymeSubstrate').onchange=e=>{w.substrate=e.target.value||'fit';e.target.value=w.substrate;w.enzymeStep=0;save();draw();};$('#stepEnzyme').onclick=()=>{w.enzymeStep=enzymeState(w.substrate,w.enzymeStep+1).step;if(w.enzymeStep>=1&&!w.fitSeen.includes(w.substrate))w.fitSeen.push(w.substrate);if(w.enzymeStep===3)w.productObserved=true;save();draw();};$('#reuseEnzyme').onclick=()=>{if(w.enzymeStep!==3){feedback('Complete the product-release stage first.',true);return;}w.enzymeCycles++;w.enzymeStep=0;w.substrate='fit';save();draw();};$('#enzymeReason').onchange=e=>{w['enzymeReason'+task]=e.target.value;save();};$('#checkOrganisation').onclick=()=>{const answer=['shape','products','same'][task],evidence=task===0?w.fitSeen.includes('wrong')&&w.fitSeen.includes('fit')&&w.enzymeStep>=2:task===1?w.productObserved:w.enzymeCycles>=1&&w.enzymeStep===3;if(!evidence||w['enzymeReason'+task]!==answer){feedback(task===0?'Compare matching and different-shaped substrates, then bind the matching substrate. Active-site shape explains specificity.':task===1?'Step to products. Substrate changes into products; the enzyme remains.':'Release products and run another complete reaction with the same enzyme. It is not used up.',true);return;}finish();feedback(['The active-site shape makes enzyme action specific.','The substrate becomes products; the protein catalyst remains.','The unchanged enzyme can catalyse further reactions.'][task]);};draw();}
$('#nextOrganisation').onclick=()=>{if(!w.passed.includes(task)){feedback('Complete this challenge first.',true);return;}w.task=(task+1)%total;save();feedback('');mountOrganisation(l,p,root,{save,done,feedback});};}
